//! 64-bit signed integer expression evaluator.
//!
//! ```text
//! expr    := term    (('+' | '-') term)*
//! term    := unary   (('*' | '/' | '%') unary)*
//! unary   := '-' unary | primary
//! primary := NUMBER | '(' expr ')'
//! ```
//!
//! Evaluation uses an operator-precedence (shunting-yard) parser with explicit stacks, so deeply
//! nested input cannot overflow the call stack.

use std::fmt;
use std::io::{self, Write};

/// Evaluates each non-blank line of `input`, printing its value or `error`.
pub fn run(input: &[u8], out: &mut dyn Write) -> io::Result<()> {
    for line in input.split(|&b| b == b'\n') {
        if line.iter().all(|&b| is_blank(b)) {
            continue;
        }
        match evaluate(line) {
            Ok(value) => writeln!(out, "{value}")?,
            Err(_) => out.write_all(b"error\n")?,
        }
    }
    Ok(())
}

/// Why an expression has no value.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CalcError {
    Syntax,
    DivisionByZero,
    Overflow,
}

impl fmt::Display for CalcError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            Self::Syntax => "syntax error",
            Self::DivisionByZero => "division by zero",
            Self::Overflow => "overflow",
        })
    }
}

impl std::error::Error for CalcError {}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Op {
    Add,
    Sub,
    Mul,
    Div,
    Rem,
    Neg,
    /// An open parenthesis: a barrier on the operator stack, never applied.
    Open,
}

impl Op {
    fn binary(byte: u8) -> Option<Self> {
        Some(match byte {
            b'+' => Self::Add,
            b'-' => Self::Sub,
            b'*' => Self::Mul,
            b'/' => Self::Div,
            b'%' => Self::Rem,
            _ => return None,
        })
    }

    fn precedence(self) -> u8 {
        match self {
            Self::Open => 0,
            Self::Add | Self::Sub => 1,
            Self::Mul | Self::Div | Self::Rem => 2,
            Self::Neg => 3,
        }
    }
}

fn is_blank(byte: u8) -> bool {
    byte == b' ' || byte == b'\t'
}

/// Evaluates one expression.
pub fn evaluate(expr: &[u8]) -> Result<i64, CalcError> {
    let mut values: Vec<i64> = Vec::new();
    let mut ops: Vec<Op> = Vec::new();
    // True when the next token must start an operand (number, unary minus or '(').
    let mut expect_operand = true;
    let mut i = 0;

    while i < expr.len() {
        let byte = expr[i];
        if is_blank(byte) {
            i += 1;
            continue;
        }

        if expect_operand {
            match byte {
                b'0'..=b'9' => {
                    let (value, len) = parse_number(&expr[i..])?;
                    values.push(value);
                    i += len;
                    expect_operand = false;
                    continue;
                }
                b'-' => ops.push(Op::Neg),
                b'(' => ops.push(Op::Open),
                _ => return Err(CalcError::Syntax),
            }
        } else if byte == b')' {
            loop {
                match ops.pop() {
                    Some(Op::Open) => break,
                    Some(op) => apply(op, &mut values)?,
                    None => return Err(CalcError::Syntax),
                }
            }
        } else {
            let op = Op::binary(byte).ok_or(CalcError::Syntax)?;
            reduce(&mut ops, &mut values, op.precedence())?;
            ops.push(op);
            expect_operand = true;
        }
        i += 1;
    }

    if expect_operand {
        return Err(CalcError::Syntax);
    }
    while let Some(op) = ops.pop() {
        if op == Op::Open {
            return Err(CalcError::Syntax);
        }
        apply(op, &mut values)?;
    }
    match values.as_slice() {
        &[value] => Ok(value),
        _ => Err(CalcError::Syntax),
    }
}

/// Applies stacked operators that bind at least as tightly as `precedence` (left associativity).
fn reduce(ops: &mut Vec<Op>, values: &mut Vec<i64>, precedence: u8) -> Result<(), CalcError> {
    while let Some(&top) = ops.last() {
        if top == Op::Open || top.precedence() < precedence {
            break;
        }
        ops.pop();
        apply(top, values)?;
    }
    Ok(())
}

/// Parses the leading run of digits, returning its value and length.
fn parse_number(digits: &[u8]) -> Result<(i64, usize), CalcError> {
    let len = digits.iter().take_while(|b| b.is_ascii_digit()).count();
    let value = digits[..len].iter().try_fold(0i64, |acc, &d| {
        acc.checked_mul(10)
            .and_then(|acc| acc.checked_add(i64::from(d - b'0')))
            .ok_or(CalcError::Overflow)
    })?;
    Ok((value, len))
}

fn apply(op: Op, values: &mut Vec<i64>) -> Result<(), CalcError> {
    let rhs = values.pop().ok_or(CalcError::Syntax)?;
    let result = if op == Op::Neg {
        rhs.checked_neg().ok_or(CalcError::Overflow)?
    } else {
        let lhs = values.pop().ok_or(CalcError::Syntax)?;
        binary(op, lhs, rhs)?
    };
    values.push(result);
    Ok(())
}

fn binary(op: Op, lhs: i64, rhs: i64) -> Result<i64, CalcError> {
    let overflow = CalcError::Overflow;
    match op {
        Op::Add => lhs.checked_add(rhs).ok_or(overflow),
        Op::Sub => lhs.checked_sub(rhs).ok_or(overflow),
        Op::Mul => lhs.checked_mul(rhs).ok_or(overflow),
        Op::Div if rhs == 0 => Err(CalcError::DivisionByZero),
        Op::Div => lhs.checked_div(rhs).ok_or(overflow),
        Op::Rem if rhs == 0 => Err(CalcError::DivisionByZero),
        // `i64::MIN % -1` is mathematically 0; only the quotient overflows.
        Op::Rem => Ok(lhs.wrapping_rem(rhs)),
        Op::Neg | Op::Open => unreachable!("{op:?} is not a binary operator"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn eval(s: &str) -> Result<i64, CalcError> {
        evaluate(s.as_bytes())
    }

    #[test]
    fn precedence_and_associativity() {
        assert_eq!(eval("1 + 2 * 3"), Ok(7));
        assert_eq!(eval("(1 + 2) * 3"), Ok(9));
        assert_eq!(eval("1 + 2 * 3 - 4 / 2 % 3"), Ok(5));
        assert_eq!(eval("10 - 4 - 3"), Ok(3));
        assert_eq!(eval("100 / 10 / 5"), Ok(2));
        assert_eq!(eval("-2 * 3"), Ok(-6));
        assert_eq!(eval("- (2 + 3) * 2"), Ok(-10));
        assert_eq!(eval("--5"), Ok(5));
        assert_eq!(eval("1 - -2"), Ok(3));
        assert_eq!(eval("\t(\t(7)\t)"), Ok(7));
    }

    #[test]
    fn division_semantics() {
        assert_eq!(eval("-7 / 2"), Ok(-3));
        assert_eq!(eval("-7 % 3"), Ok(-1));
        assert_eq!(eval("7 % -3"), Ok(1));
        assert_eq!(eval("1 / 0"), Err(CalcError::DivisionByZero));
        assert_eq!(eval("1 % 0"), Err(CalcError::DivisionByZero));
        assert_eq!(eval("(-9223372036854775807 - 1) % -1"), Ok(0));
        assert_eq!(eval("(-9223372036854775807 - 1) / -1"), Err(CalcError::Overflow));
    }

    #[test]
    fn overflow() {
        assert_eq!(eval("9223372036854775807"), Ok(i64::MAX));
        assert_eq!(eval("9223372036854775808"), Err(CalcError::Overflow));
        assert_eq!(eval("-9223372036854775808"), Err(CalcError::Overflow));
        assert_eq!(eval("9223372036854775807 + 1"), Err(CalcError::Overflow));
        assert_eq!(eval("-(-9223372036854775807 - 1)"), Err(CalcError::Overflow));
        assert_eq!(eval("3037000500 * 3037000500"), Err(CalcError::Overflow));
    }

    #[test]
    fn syntax_errors() {
        for s in ["1 +", "abc", "()", "1 2", "+1", "(1 + 2", "1 + 2)", ")", "1 (2)", "(1)(2)", "1 - - ", "1\r", "* 2"] {
            assert_eq!(eval(s), Err(CalcError::Syntax), "{s:?}");
        }
    }

    #[test]
    fn deep_nesting() {
        let depth = 1_000_000;
        let s = format!("{}1{}", "(".repeat(depth), ")".repeat(depth));
        assert_eq!(eval(&s), Ok(1));
        assert_eq!(eval(&format!("{}1", "-".repeat(depth + 1))), Ok(-1));
    }

    #[test]
    fn blank_lines_print_nothing() {
        let mut out = Vec::new();
        run(b"\n  42  \n\t\n1+1\n1/0", &mut out).unwrap();
        assert_eq!(out, b"42\n2\nerror\n");
    }
}

//! LRU cache simulator.
//!
//! The first input line holds the capacity; every later line is a `SET`, `GET`, `DEL` or `SIZE`
//! command. Entries live in a slab threaded by an intrusive doubly linked list (most recently used
//! at the head), indexed by a hash map from key to slab slot, so every command is O(1) expected.

use std::collections::HashMap;
use std::io::{self, Write};

/// Runs the commands in `input` and writes one line per `GET`, `DEL` and `SIZE`.
pub fn run(input: &[u8], out: &mut dyn Write) -> io::Result<()> {
    let mut lines = input.split(|&b| b == b'\n').map(trim_cr);
    let capacity = lines
        .next()
        .and_then(|line| std::str::from_utf8(line).ok())
        .and_then(|s| s.trim().parse::<usize>().ok())
        .filter(|&c| c >= 1)
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "lru: invalid capacity line"))?;

    let mut cache = LruCache::new(capacity);
    for line in lines {
        let mut tokens = line.split(|&b| b == b' ').filter(|t| !t.is_empty());
        match (tokens.next(), tokens.next(), tokens.next()) {
            (Some(b"SET"), Some(key), Some(value)) => cache.set(key, value),
            (Some(b"GET"), Some(key), _) => match cache.get(key) {
                Some(value) => {
                    out.write_all(value)?;
                    out.write_all(b"\n")?;
                }
                None => out.write_all(b"NULL\n")?,
            },
            (Some(b"DEL"), Some(key), _) => {
                out.write_all(if cache.remove(key) { b"1\n" } else { b"0\n" })?;
            }
            (Some(b"SIZE"), _, _) => writeln!(out, "{}", cache.len())?,
            // Blank or malformed lines are not commands; they produce no output.
            _ => {}
        }
    }
    Ok(())
}

fn trim_cr(line: &[u8]) -> &[u8] {
    line.strip_suffix(b"\r").unwrap_or(line)
}

/// Slab index meaning "no node".
const NIL: usize = usize::MAX;

struct Node {
    key: Box<[u8]>,
    value: Vec<u8>,
    prev: usize,
    next: usize,
}

/// A fixed-capacity map that evicts its least recently used entry when full.
pub struct LruCache {
    capacity: usize,
    index: HashMap<Box<[u8]>, usize>,
    nodes: Vec<Node>,
    free: Vec<usize>,
    head: usize,
    tail: usize,
}

impl LruCache {
    /// Creates an empty cache holding at most `capacity` keys (`capacity` ≥ 1).
    pub fn new(capacity: usize) -> Self {
        assert!(capacity >= 1, "LRU capacity must be at least 1");
        Self {
            capacity,
            index: HashMap::new(),
            nodes: Vec::new(),
            free: Vec::new(),
            head: NIL,
            tail: NIL,
        }
    }

    /// Number of keys currently held.
    pub fn len(&self) -> usize {
        self.index.len()
    }

    /// Returns the value for `key`, marking it most recently used.
    pub fn get(&mut self, key: &[u8]) -> Option<&[u8]> {
        let slot = *self.index.get(key)?;
        self.move_to_front(slot);
        Some(&self.nodes[slot].value)
    }

    /// Inserts or overwrites `key`, marking it most recently used and evicting if over capacity.
    pub fn set(&mut self, key: &[u8], value: &[u8]) {
        if let Some(&slot) = self.index.get(key) {
            let node = &mut self.nodes[slot];
            node.value.clear();
            node.value.extend_from_slice(value);
            self.move_to_front(slot);
            return;
        }

        let node = Node {
            key: key.into(),
            value: value.to_vec(),
            prev: NIL,
            next: NIL,
        };
        let slot = match self.free.pop() {
            Some(slot) => {
                self.nodes[slot] = node;
                slot
            }
            None => {
                self.nodes.push(node);
                self.nodes.len() - 1
            }
        };
        self.index.insert(key.into(), slot);
        self.push_front(slot);

        if self.index.len() > self.capacity {
            let lru = self.tail;
            self.evict(lru);
        }
    }

    /// Removes `key`, reporting whether it was present.
    pub fn remove(&mut self, key: &[u8]) -> bool {
        match self.index.get(key) {
            Some(&slot) => {
                self.evict(slot);
                true
            }
            None => false,
        }
    }

    fn evict(&mut self, slot: usize) {
        self.unlink(slot);
        let node = &mut self.nodes[slot];
        self.index.remove(&node.key);
        node.key = Box::default();
        node.value = Vec::new();
        self.free.push(slot);
    }

    fn move_to_front(&mut self, slot: usize) {
        if self.head != slot {
            self.unlink(slot);
            self.push_front(slot);
        }
    }

    fn push_front(&mut self, slot: usize) {
        let old_head = self.head;
        let node = &mut self.nodes[slot];
        node.prev = NIL;
        node.next = old_head;
        match old_head {
            NIL => self.tail = slot,
            h => self.nodes[h].prev = slot,
        }
        self.head = slot;
    }

    fn unlink(&mut self, slot: usize) {
        let Node { prev, next, .. } = self.nodes[slot];
        match prev {
            NIL => self.head = next,
            p => self.nodes[p].next = next,
        }
        match next {
            NIL => self.tail = prev,
            n => self.nodes[n].prev = prev,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn render(input: &str) -> String {
        let mut out = Vec::new();
        run(input.as_bytes(), &mut out).unwrap();
        String::from_utf8(out).unwrap()
    }

    #[test]
    fn spec_example() {
        assert_eq!(render("2\nSET a 1\nSET b 2\nGET a\nSET c 3\nGET b\nSIZE\n"), "1\nNULL\n2\n");
    }

    #[test]
    fn overwrite_refreshes_recency() {
        assert_eq!(render("2\nSET a 1\nSET b 2\nSET a 9\nSET c 3\nGET a\nGET b\nGET c"), "9\nNULL\n3\n");
    }

    #[test]
    fn delete_and_reuse_slots() {
        assert_eq!(
            render("2\nSET x 1\nDEL x\nDEL x\nSIZE\nSET y 2\nSET z 3\nSET w 4\nGET y\nGET z\nGET w\nSIZE"),
            "1\n0\n0\nNULL\n3\n4\n2\n"
        );
    }

    #[test]
    fn capacity_one() {
        assert_eq!(render("1\nSET a 1\nSET b 2\nGET a\nGET b\nSIZE\n"), "NULL\n2\n1\n");
    }
}

//! `suite`: a command-line program with three independent subcommands.
//!
//! - `wordfreq`: the ten most frequent words of standard input.
//! - `lru`: an LRU cache simulator driven by commands on standard input.
//! - `calc`: a 64-bit signed integer expression evaluator, one expression per line.

mod calc;
mod lru;
mod wordfreq;

use std::io::{self, BufWriter, Read, Write};
use std::process::ExitCode;

type Command = fn(&[u8], &mut dyn Write) -> io::Result<()>;

fn main() -> ExitCode {
    let name = std::env::args().nth(1);
    let command: Command = match name.as_deref() {
        Some("wordfreq") => wordfreq::run,
        Some("lru") => lru::run,
        Some("calc") => calc::run,
        _ => {
            eprintln!("usage: app <wordfreq|lru|calc>  (reads standard input)");
            return ExitCode::from(2);
        }
    };

    match execute(command) {
        Ok(()) => ExitCode::SUCCESS,
        // A closed stdout (e.g. piping into `head`) is not a failure of the program.
        Err(e) if e.kind() == io::ErrorKind::BrokenPipe => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("app: {e}");
            ExitCode::FAILURE
        }
    }
}

fn execute(command: Command) -> io::Result<()> {
    let mut input = Vec::new();
    io::stdin().lock().read_to_end(&mut input)?;

    let mut out = BufWriter::with_capacity(1 << 16, io::stdout().lock());
    command(&input, &mut out)?;
    out.flush()
}

//! Word frequency counting.
//!
//! A word is a maximal run of ASCII letters, folded to lowercase; every other byte separates words.

use std::collections::HashMap;
use std::io::{self, Write};

/// How many of the most frequent words are reported.
const TOP: usize = 10;

/// Prints the most frequent words of `input` as `<count> <word>` lines.
pub fn run(input: &[u8], out: &mut dyn Write) -> io::Result<()> {
    for (word, count) in top_words(&count_words(input), TOP) {
        writeln!(out, "{count} {}", String::from_utf8_lossy(word))?;
    }
    Ok(())
}

/// Counts every lowercase-folded word in `input`.
fn count_words(input: &[u8]) -> HashMap<Vec<u8>, u64> {
    let mut counts: HashMap<Vec<u8>, u64> = HashMap::new();
    let mut word = Vec::with_capacity(64);

    for run in input.split(|b| !b.is_ascii_alphabetic()) {
        if run.is_empty() {
            continue;
        }
        word.clear();
        word.extend(run.iter().map(u8::to_ascii_lowercase));
        match counts.get_mut(word.as_slice()) {
            Some(count) => *count += 1,
            None => {
                counts.insert(word.clone(), 1);
            }
        }
    }
    counts
}

/// Returns up to `n` entries ordered by count descending, then word ascending.
fn top_words(counts: &HashMap<Vec<u8>, u64>, n: usize) -> Vec<(&[u8], u64)> {
    let mut entries: Vec<(&[u8], u64)> = counts.iter().map(|(w, &c)| (w.as_slice(), c)).collect();
    let order = |a: &(&[u8], u64), b: &(&[u8], u64)| b.1.cmp(&a.1).then_with(|| a.0.cmp(b.0));

    if entries.len() > n {
        entries.select_nth_unstable_by(n, order);
        entries.truncate(n);
    }
    entries.sort_unstable_by(order);
    entries
}

#[cfg(test)]
mod tests {
    use super::*;

    fn render(input: &[u8]) -> String {
        let mut out = Vec::new();
        run(input, &mut out).unwrap();
        String::from_utf8(out).unwrap()
    }

    #[test]
    fn spec_example() {
        assert_eq!(render(b"The cat and the hat."), "2 the\n1 and\n1 cat\n1 hat\n");
    }

    #[test]
    fn separators_and_invalid_utf8() {
        assert_eq!(render(b"don't\xffstop_me 4now, now-NOW\xc3("), "3 now\n1 don\n1 me\n1 stop\n1 t\n");
    }

    #[test]
    fn empty_and_wordless_input() {
        assert_eq!(render(b""), "");
        assert_eq!(render(b"123 ,.-_ \x80\xff"), "");
    }

    #[test]
    fn keeps_only_top_ten() {
        let text = "a b c d e f g h i j k l a";
        assert_eq!(render(text.as_bytes()).lines().count(), 10);
        assert!(render(text.as_bytes()).starts_with("2 a\n1 b\n"));
        assert!(render(text.as_bytes()).ends_with("1 j\n"));
    }
}
